const totalSections = body.totalSections;
const sectionHeading = body.sectionHeading || 'Untitled Section';
const htmlContentEncoded = body.htmlContent;
const htmlContentEncoding = body.htmlContentEncoding || 'base64';
const moreData = body.moreData !== undefined ? body.moreData : false;
const options = body.options || {};

