// This ensures it matches the specName stored in Supabase
const specNameForQuery = specName.replace(/\s+v\d+.*$/i, '').trim();
console.log('[Validate] Original specName:', specName);
console.log('[Validate] specName for query:', specNameForQuery);

let htmlContent;
try { if (htmlContentEncoding === 'base64') { htmlContent = Buffer.from(htmlContentEncoded, 'base64').toString('utf8'); } else { htmlContent = htmlContentEncoded; } } catch (e) { throw new Error('Failed to decode htmlContent: ' + e.message); }

