// Build the complete OpenAI API request
// The AI needs the FULL specification text to compare against the document section
const inputData = $('Validate Input & Extract Keywords').item.json;
const specsData = $('Fetch All Specs').all();

console.log('[Build Prompt] Received specs count:', specsData.length);
console.log('[Build Prompt] Looking for specName:', inputData.specNameForQuery);
console.log('[Build Prompt] Input heading:', inputData.heading);

// Find the matching spec by specName
// The Supabase table has one row per degree type (Associate, Bachelor's, Master's)
// Each row contains the FULL specification text in the 'content' field
let matchingSpec = null;
let fullSpecContent = '';

for (const item of specsData) {
  const spec = item.json;

  // The specName might be a direct field or in metadata
  const specName = spec.specName || (typeof spec.metadata === 'string' ? JSON.parse(spec.metadata).specName : spec.metadata?.specName);

  console.log('[Build Prompt] Checking spec:', specName ? specName.substring(0, 50) : 'no specName');

  if (!specName) {
    continue;
  }

  // Case-insensitive comparison
  const queryLower = inputData.specNameForQuery.toLowerCase();
  const specNameLower = specName.toLowerCase();

  if (specNameLower.includes(queryLower) || queryLower.includes(specNameLower)) {
    matchingSpec = spec;
    fullSpecContent = spec.content || '';
    console.log('[Build Prompt] Found matching spec! Content length:', fullSpecContent.length);
    break;
  }
}

if (!matchingSpec || !fullSpecContent) {
  console.log('[Build Prompt] ERROR: No matching spec found for:', inputData.specNameForQuery);
  console.log('[Build Prompt] Available specs:', specsData.map(s => s.json.specName || s.json.metadata?.specName).join(', '));
  throw new Error('No matching specification found for: ' + inputData.specNameForQuery);
}

console.log('[Build Prompt] Full spec content length:', fullSpecContent.length);

