// Parse the OpenAI API response and extract classification result
// Also pass through the input data for the callback node
const apiResponse = $input.first().json;

console.log('[Parse LLM] Received API response');

let aiOutput = null;

// Extract the message content from OpenAI response
try {
  let responseText = '';

  if (apiResponse.choices && apiResponse.choices[0]?.message?.content) {
    responseText = apiResponse.choices[0].message.content;
    console.log('[Parse LLM] Extracted content from choices');
  } else if (apiResponse.message?.content) {
    responseText = apiResponse.message.content;
  } else if (typeof apiResponse === 'string') {
    responseText = apiResponse;
  } else {
    console.log('[Parse LLM] Unexpected response structure');
    responseText = JSON.stringify(apiResponse);
  }

  console.log('[Parse LLM] Response preview:', responseText.substring(0, 200));

  // Parse the JSON response
  aiOutput = JSON.parse(responseText);
  console.log('[Parse LLM] Successfully parsed JSON');

} catch (parseError) {
  console.log('[Parse LLM] Parse error:', parseError.message);

  try {
    const responseText = apiResponse.choices?.[0]?.message?.content || '';
    const jsonMatch = responseText.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      aiOutput = JSON.parse(jsonMatch[0]);
    }
  } catch (e2) {
    console.log('[Parse LLM] Secondary parse failed');
  }
}

// Default if parsing failed
if (!aiOutput) {
  aiOutput = {
    status: 'unmatched',
    standardCode: null,
    standardTitle: null,
    subspecificationCode: null,
    subspecificationTitle: null,
    confidence: 0,
    rationale: 'Failed to parse AI response'
  };
}

// Normalize the result
const result = {
  status: aiOutput.status || 'unmatched',
  standardCode: aiOutput.standardCode ? String(aiOutput.standardCode) : null,
  standardTitle: aiOutput.standardTitle ? String(aiOutput.standardTitle) : null,
  subspecificationCode: aiOutput.subspecificationCode ? String(aiOutput.subspecificationCode) : null,
  subspecificationTitle: aiOutput.subspecificationTitle ? String(aiOutput.subspecificationTitle) : null,
  confidence: typeof aiOutput.confidence === 'number' ? aiOutput.confidence : parseInt(aiOutput.confidence, 10) || 0,
  rationale: aiOutput.rationale ? String(aiOutput.rationale) : 'No rationale provided'
};

console.log('[Parse LLM] Final result:', JSON.stringify(result));

return [{ json: result }];
